-- Permission vocabulary and system roles of the bulkops module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the bulkops permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('bulk_job:create'::text, 'bulk_job'::text, 'create'::text, 'Create bulk job'::text),
            ('bulk_job:delete'::text, 'bulk_job'::text, 'delete'::text, 'Delete bulk job'::text),
            ('bulk_job:purge'::text, 'bulk_job'::text, 'purge'::text, 'Purge bulk job'::text),
            ('bulk_job:read'::text, 'bulk_job'::text, 'read'::text, 'Read bulk job'::text),
            ('bulk_job:restore'::text, 'bulk_job'::text, 'restore'::text, 'Restore bulk job'::text),
            ('bulk_job:update'::text, 'bulk_job'::text, 'update'::text, 'Update bulk job'::text),
            ('bulk_job_item:create'::text, 'bulk_job_item'::text, 'create'::text, 'Create bulk job item'::text),
            ('bulk_job_item:delete'::text, 'bulk_job_item'::text, 'delete'::text, 'Delete bulk job item'::text),
            ('bulk_job_item:purge'::text, 'bulk_job_item'::text, 'purge'::text, 'Purge bulk job item'::text),
            ('bulk_job_item:read'::text, 'bulk_job_item'::text, 'read'::text, 'Read bulk job item'::text),
            ('bulk_job_item:restore'::text, 'bulk_job_item'::text, 'restore'::text, 'Restore bulk job item'::text),
            ('bulk_job_item:update'::text, 'bulk_job_item'::text, 'update'::text, 'Update bulk job item'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('bulk_job:create'::text, 'bulk_job'::text, 'create'::text, 'Create bulk job'::text),
            ('bulk_job:delete'::text, 'bulk_job'::text, 'delete'::text, 'Delete bulk job'::text),
            ('bulk_job:purge'::text, 'bulk_job'::text, 'purge'::text, 'Purge bulk job'::text),
            ('bulk_job:read'::text, 'bulk_job'::text, 'read'::text, 'Read bulk job'::text),
            ('bulk_job:restore'::text, 'bulk_job'::text, 'restore'::text, 'Restore bulk job'::text),
            ('bulk_job:update'::text, 'bulk_job'::text, 'update'::text, 'Update bulk job'::text),
            ('bulk_job_item:create'::text, 'bulk_job_item'::text, 'create'::text, 'Create bulk job item'::text),
            ('bulk_job_item:delete'::text, 'bulk_job_item'::text, 'delete'::text, 'Delete bulk job item'::text),
            ('bulk_job_item:purge'::text, 'bulk_job_item'::text, 'purge'::text, 'Purge bulk job item'::text),
            ('bulk_job_item:read'::text, 'bulk_job_item'::text, 'read'::text, 'Read bulk job item'::text),
            ('bulk_job_item:restore'::text, 'bulk_job_item'::text, 'restore'::text, 'Restore bulk job item'::text),
            ('bulk_job_item:update'::text, 'bulk_job_item'::text, 'update'::text, 'Update bulk job item'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
